/**
 * @name Zip Slip
 * @description Extracting files from a malicious zip archive without validating that the destination file path is within the destination directory can allow an attacker to overwrite arbitrary files.
 * @kind path-problem
 * @problem.severity error
 * @id py/zip-slip
 * @tags security
 *       external/cwe/cwe-022
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.Concepts
import semmle.python.ApiGraphs

module ZipSlipConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    // Source is the filename from a ZipInfo object or similar
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("zipfile").getMember("ZipFile").getReturn().getMember("namelist").getACall() and
      source = call
    )
    or
    exists(DataFlow::CallCfgNode call |
        call = API::moduleImport("zipfile").getMember("ZipFile").getReturn().getMember("infolist").getACall() and
        source = call
    )
  }

  predicate isSink(DataFlow::Node sink) {
    sink = any(FileSystemAccess fa).getAPathArgument()
  }
}

module ZipSlipFlow = TaintTracking::Global<ZipSlipConfig>;
import ZipSlipFlow::PathGraph

from ZipSlipFlow::PathNode source, ZipSlipFlow::PathNode sink
where ZipSlipFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Potential Zip Slip vulnerability from $@.", source.getNode(), "zip archive content"

/**
 * @name Zip Slip Vulnerability
 * @description Extracting files from a malicious zip archive without validating file paths can allow writing files outside the destination directory.
 * @kind path-problem
 * @problem.severity error
 * @id py/zip-slip
 * @tags security
 *       external/cwe/cwe-022
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.ApiGraphs
import semmle.python.Concepts

module ZipSlipConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    // Source: Filenames coming from zipfile.ZipFile.namelist() or similar
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("zipfile").getMember("ZipFile").getReturn().getMember("namelist").getACall() and
      source = call
    )
    or
    // Source: ZipInfo objects from zipfile.ZipFile.infolist() or .getinfo()
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("zipfile").getMember("ZipFile").getReturn().getMember(["infolist", "getinfo"]).getACall() and
      source = call
    )
  }

  predicate isSink(DataFlow::Node sink) {
    // Sink: File open or write operations where the path is used
    sink = any(FileSystemAccess fa).getAPathArgument()
  }
}

module ZipSlipFlow = TaintTracking::Global<ZipSlipConfig>;
import ZipSlipFlow::PathGraph

from ZipSlipFlow::PathNode source, ZipSlipFlow::PathNode sink
where ZipSlipFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Potential Zip Slip vulnerability: file path from zip archive used in file operation."

/**
 * @name Zip Slip in WheelFile
 * @description Extracting files from a malicious wheel (zip) archive without validating file paths can allow writing files outside the destination directory.
 * @kind path-problem
 * @problem.severity error
 * @id py/wheel-zip-slip
 * @tags security
 *       external/cwe/cwe-022
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.ApiGraphs
import semmle.python.Concepts

module ZipSlipConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    // Source: Filenames coming from zipfile.ZipFile.namelist() or similar
    // We also want to catch subclasses like WheelFile
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("zipfile").getMember("ZipFile").getASubclass*().getReturn().getMember("namelist").getACall() and
      source = call
    )
    or
    // Source: ZipInfo objects from zipfile.ZipFile.infolist() or .getinfo()
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("zipfile").getMember("ZipFile").getASubclass*().getReturn().getMember(["infolist", "getinfo"]).getACall() and
      source = call
    )
  }

  predicate isSink(DataFlow::Node sink) {
    // Sink: File open or write operations where the path is used
    sink = any(FileSystemAccess fa).getAPathArgument()
  }
}

module ZipSlipFlow = TaintTracking::Global<ZipSlipConfig>;
import ZipSlipFlow::PathGraph

from ZipSlipFlow::PathNode source, ZipSlipFlow::PathNode sink
where ZipSlipFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Potential Zip Slip vulnerability: file path from zip archive used in file operation."
